function MillHopperLubricatorMaker.init() MillHopperLubricatorMaker.ironStock=12; MillHopperLubricatorMaker.bronzeStock=10; MillHopperLubricatorMaker.woodStock=14; MillHopperLubricatorMaker.leatherStock=10; MillHopperLubricatorMaker.silverStock=8; MillHopperLubricatorMaker.goldStock=6; MillHopperLubricatorMaker.jewelStock=4; MillHopperLubricatorMaker.pearlStock=4; MillHopperLubricatorMaker.productStock={}; MillHopperLubricatorMaker.buildings={}; MillHopperLubricatorMaker.maker=nil; MillHopperLubricatorMaker.activeMaking={}; MillHopperLubricatorMaker.totalProducts=0; MillHopperLubricatorMaker.dayTimer=0; print("[MillHopperLubricatorMaker] Royal Mill Hopper Lubricator Maker System initialized (6 products, 4 buildings)") end
function MillHopperLubricatorMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillHopperLubricatorMaker.maker={name=n or ("Mazalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mazalec najet: %s (spretnost: %d)",MillHopperLubricatorMaker.maker.name,s),"success") end; return true end
function MillHopperLubricatorMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillHopperLubricatorMaker.build(id) local ok,e=MillHopperLubricatorMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillHopperLubricatorMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillHopperLubricatorMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillHopperLubricatorMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillHopperLubricatorMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillHopperLubricatorMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillHopperLubricatorMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillHopperLubricatorMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillHopperLubricatorMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillHopperLubricatorMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillHopperLubricatorMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillHopperLubricatorMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillHopperLubricatorMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillHopperLubricatorMaker.buildings==0 then return false,"Potrebna mazalna delavnica" end; if not MillHopperLubricatorMaker.maker then return false,"Potreben mazalec" end; return true end
function MillHopperLubricatorMaker.make(pt,qty) qty=qty or 1; local ok,e=MillHopperLubricatorMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillHopperLubricatorMaker.ironStock=MillHopperLubricatorMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillHopperLubricatorMaker.bronzeStock=MillHopperLubricatorMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillHopperLubricatorMaker.woodStock=MillHopperLubricatorMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillHopperLubricatorMaker.leatherStock=MillHopperLubricatorMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillHopperLubricatorMaker.silverStock=MillHopperLubricatorMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillHopperLubricatorMaker.goldStock=MillHopperLubricatorMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillHopperLubricatorMaker.jewelStock=MillHopperLubricatorMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillHopperLubricatorMaker.pearlStock=MillHopperLubricatorMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillHopperLubricatorMaker.maker then t=math.max(1,t-math.floor(MillHopperLubricatorMaker.maker.skill/13)) end; table.insert(MillHopperLubricatorMaker.activeMaking,{id="millhopperlubricator_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillHopperLubricatorMaker.completeMaking(m) local q=1.0+(MillHopperLubricatorMaker.getQualityBonus()/100); if MillHopperLubricatorMaker.maker then q=q+(MillHopperLubricatorMaker.maker.skill/140) end; q=math.min(2.5,q); MillHopperLubricatorMaker.productStock[m.productType]=(MillHopperLubricatorMaker.productStock[m.productType] or 0)+m.quantity; MillHopperLubricatorMaker.totalProducts=MillHopperLubricatorMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillHopperLubricatorMaker.maker then MillHopperLubricatorMaker.maker.itemsMade=MillHopperLubricatorMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillHopperLubricatorMaker.maker.skill=math.min(100,MillHopperLubricatorMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mazalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millhopperlubricator.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillHopperLubricatorMaker.update(dt) if not _G.state then return end; MillHopperLubricatorMaker.dayTimer=MillHopperLubricatorMaker.dayTimer+dt; if MillHopperLubricatorMaker.dayTimer>=30 then MillHopperLubricatorMaker.dayTimer=0; for i=#MillHopperLubricatorMaker.activeMaking,1,-1 do local m=MillHopperLubricatorMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillHopperLubricatorMaker.completeMaking(m); table.remove(MillHopperLubricatorMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillHopperLubricatorMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillHopperLubricatorMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MillHopperLubricatorMaker.getStats() return {ironStock=MillHopperLubricatorMaker.ironStock,bronzeStock=MillHopperLubricatorMaker.bronzeStock,woodStock=MillHopperLubricatorMaker.woodStock,leatherStock=MillHopperLubricatorMaker.leatherStock,silverStock=MillHopperLubricatorMaker.silverStock,goldStock=MillHopperLubricatorMaker.goldStock,jewelStock=MillHopperLubricatorMaker.jewelStock,pearlStock=MillHopperLubricatorMaker.pearlStock,productStock=MillHopperLubricatorMaker.productStock,numBuildings=#MillHopperLubricatorMaker.buildings,hasMaker=MillHopperLubricatorMaker.maker~=nil,makerName=MillHopperLubricatorMaker.maker and MillHopperLubricatorMaker.maker.name or "—",makerSkill=MillHopperLubricatorMaker.maker and MillHopperLubricatorMaker.maker.skill or 0,activeMaking=#MillHopperLubricatorMaker.activeMaking,totalProducts=MillHopperLubricatorMaker.totalProducts} end
